package org.local.karbalascreen;
import android.app.*;
import android.os.*;
import android.widget.*;
import org.json.*;
import java.util.*;
/** Remote-friendly explicit search/detection; guesses never silently become active locations. */
public final class LocationActivity extends Activity {
 private LinearLayout list,results;private EditText query;private TextView status;private CancellationSignal signal;private Thread worker;
 @Override public void onCreate(Bundle state){super.onCreate(state);ScrollView scroll=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);list.setPadding(40,24,40,24);scroll.addView(list);setContentView(scroll);
  label("المدينة والتوقيت ومواقيت الصلاة");LocationProfile current=LocationStore.read(new Options(this).prefs);label(current==null?"اختر مدينة لبدء طلب الطقس والمواقيت والتنبيهات":current.city+" · "+current.country+" · "+current.timezone+"\n"+current.source());
  query=new EditText(this);query.setSingleLine(true);query.setHint("اسم المدينة، البلد");list.addView(query);button("بحث عن مدينة · Open-Meteo / GeoNames",()->search(false));
  button("اقتراح موقع تقريبي عبر عنوان الإنترنت",()->new AlertDialog.Builder(this).setMessage("يرسل هذا الطلب عنوان الإنترنت إلى ipwho.is لاستخراج مدينة تقريبية. قد يكون الاقتراح خاطئاً مع VPN؛ راجع المدينة والتوقيت قبل التأكيد. لا يُحفظ عنوان الإنترنت، ولا يوجد تتبّع مستمر أو GPS.").setPositiveButton("اطلب اقتراحاً الآن",(d,w)->search(true)).setNegativeButton("إلغاء",null).show());
  button("كربلاء · اختيار صريح لمصدر العتبة العباسية",()->confirm(LocationProfile.karbala()));
  if(current!=null){button("طريقة حساب المواقيت",()->method(current));button("تصحيح دقائق الفجر والظهر والعشاء",()->offsets(current));}
  status=label("");results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);list.addView(results);label("المصدر الرسمي المؤرخ متاح لكربلاء فقط عند اختياره صراحة. المدن الأخرى: AlAdhan، جعفري افتراضياً، ويمكن تغيير الطريقة. الإمساك الحسابي ليس توقيتاً موثقاً من العتبة. توقيت الصلاة يحتاج مراجعة مع الجهة المحلية، وخاصة عند خطوط العرض العالية.\nOpen-Meteo / GeoNames: CC BY 4.0 · https://open-meteo.com/en/docs/geocoding-api\nhttps://ipwhois.io/documentation · https://aladhan.com/prayer-times-api");
 }
 private TextView label(String text){TextView v=new TextView(this);v.setAutoLinkMask(android.text.util.Linkify.WEB_URLS);v.setText(text);v.setTypeface(InfoFonts.sans(this));v.setTextSize(18);v.setPadding(8,10,8,10);list.addView(v);return v;}
 private void button(String text,Runnable action){Button b=new Button(this);b.setText(text);b.setAllCaps(false);b.setOnClickListener(v->action.run());list.addView(b);}
 private void search(boolean ip){if(signal!=null)signal.cancel();if(worker!=null)worker.interrupt();String term=query.getText().toString().trim();if(!ip&&term.length()<2){status.setText("اكتب حرفين على الأقل");return;}CancellationSignal request=new CancellationSignal();signal=request;status.setText("جارٍ البحث…");results.removeAllViews();worker=new Thread(()->{try{List<LocationProfile> found=new ArrayList<>();if(ip){JSONObject j=JsonHttp.get("https://ipwho.is/?fields=success,city,country,latitude,longitude,timezone",request);if(!j.optBoolean("success"))throw new IllegalArgumentException();found.add(new LocationProfile(j.getString("city"),j.getString("country"),j.getDouble("latitude"),j.getDouble("longitude"),j.getJSONObject("timezone").getString("id"),false,0,0,0,0));}else{JSONObject j=JsonHttp.get("https://geocoding-api.open-meteo.com/v1/search?name="+JsonHttp.encode(term)+"&count=10&language=ar&format=json",request);JSONArray a=j.optJSONArray("results");if(a!=null)for(int i=0;i<a.length();i++){JSONObject v=a.getJSONObject(i);try{found.add(new LocationProfile(v.getString("name"),v.optString("country",""),v.getDouble("latitude"),v.getDouble("longitude"),v.getString("timezone"),false,0,0,0,0));}catch(Exception invalid){/* No guessed timezone. */}}}runOnUiThread(()->{if(request.isCanceled()||isFinishing())return;status.setText(found.isEmpty()?"لا نتائج صالحة؛ جرّب اسماً آخر":ip?"اقتراح تقريبي؛ اضغط للمراجعة والتأكيد":"اختر النتيجة ثم أكّد");for(LocationProfile p:found){Button b=new Button(this);b.setAllCaps(false);b.setText(p.city+" · "+p.country+" · "+p.timezone+"\n"+p.latitude+", "+p.longitude);b.setOnClickListener(v->confirm(p));results.addView(b);}});}catch(Exception failure){runOnUiThread(()->{if(!request.isCanceled()&&!isFinishing())status.setText("تعذر البحث. تحقق من الإنترنت أو ابحث يدوياً.");});}},"city-search");worker.start();}
 private void confirm(LocationProfile p){new AlertDialog.Builder(this).setTitle("تأكيد المدينة والتوقيت").setMessage(p.city+" · "+p.country+"\n"+p.timezone+"\n"+p.latitude+", "+p.longitude+"\n"+p.source()+"\nسيتم إلغاء التنبيهات والبيانات السابقة وتحديثها لهذه المدينة.").setPositiveButton("تطبيق",(d,w)->{LocationStore.apply(this,p);recreate();}).setNegativeButton("إلغاء",null).show();}
 private void method(LocationProfile p){String[] names={"جعفري Ithna Ashari (0)","طهران (7)","رابطة العالم الإسلامي (3)","أم القرى (4)","الهيئة المصرية (5)","ISNA (2)"};int[] ids={0,7,3,4,5,2};new AlertDialog.Builder(this).setTitle("مصدر حسابي · AlAdhan").setItems(names,(d,w)->confirm(new LocationProfile(p.city,p.country,p.latitude,p.longitude,p.timezone,false,ids[w],p.offsets[0],p.offsets[1],p.offsets[2]))).setNegativeButton("إلغاء",null).show();}
 private void offsets(LocationProfile p){LinearLayout fields=new LinearLayout(this);fields.setOrientation(LinearLayout.VERTICAL);EditText[] values=new EditText[3];String[] names={"الفجر","الظهر","العشاء"};for(int i=0;i<3;i++){TextView n=new TextView(this);n.setText(names[i]+" · من -60 إلى +60 دقيقة");fields.addView(n);values[i]=new EditText(this);values[i].setSingleLine(true);values[i].setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_SIGNED);values[i].setText(Integer.toString(p.offsets[i]));fields.addView(values[i]);}AlertDialog dialog=new AlertDialog.Builder(this).setTitle("تصحيح محلي للدقائق").setView(fields).setPositiveButton("مراجعة",null).setNegativeButton("إلغاء",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{LocationProfile changed=new LocationProfile(p.city,p.country,p.latitude,p.longitude,p.timezone,p.official,p.method,Integer.parseInt(values[0].getText().toString()),Integer.parseInt(values[1].getText().toString()),Integer.parseInt(values[2].getText().toString()));dialog.dismiss();confirm(changed);}catch(Exception invalid){Toast.makeText(this,"أدخل دقائق صحيحة بين -60 و+60",Toast.LENGTH_LONG).show();}}));dialog.show();}
 @Override public void onDestroy(){if(signal!=null)signal.cancel();if(worker!=null)worker.interrupt();super.onDestroy();}
}
